// isTerminal checks if fd is a terminal using ioctl TCGETS
func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return err == 0
}

func shouldColor() bool {
	if os.Getenv("RICHGO_FORCE_COLOR") == "1" {
		return true
	}
	return isTerminal(os.Stdout.Fd())
}

// styleToANSI converts Style to ANSI escape sequence (without reset)
func styleToANSI(s Style) string {
	var codes []string
	if s.Bold != nil && *s.Bold {
		codes = append(codes, "1")
	}
	if s.Faint != nil && *s.Faint {
		codes = append(codes, "2")
	}
	if s.Italic != nil && *s.Italic {
		codes = append(codes, "3")
	}
	if s.Underline != nil && *s.Underline {
		codes = append(codes, "4")
	}
	if s.BlinkSlow != nil && *s.BlinkSlow {
		codes = append(codes, "5")
	}
	if s.BlinkRapid != nil && *s.BlinkRapid {
		codes = append(codes, "6")
	}
	if s.Inverse != nil && *s.Inverse {
		codes = append(codes, "7")
	}
	if s.Conceal != nil && *s.Conceal {
		codes = append(codes, "8")
	}
	if s.CrossOut != nil && *s.CrossOut {
		codes = append(codes, "9")
	}
	if s.Frame != nil && *s.Frame {
		codes = append(codes, "51")
	}
	if s.Encircle != nil && *s.Encircle {
		codes = append(codes, "52")
	}
	if s.Overline != nil && *s.Overline {
		codes = append(codes, "53")
	}
	if s.Foreground != nil {
		if code := colorToCode(*s.Foreground, false); code != "" {
			codes = append(codes, code)
		}
	}
	if s.Background != nil {
		if code := colorToCode(*s.Background, true); code != "" {
			codes = append(codes, code)
		}
	}
	if len(codes) == 0 {
		return ""
	}
	return "\x1b[" + strings.Join(codes, ";") + "m"
}

func colorToCode(color string, background bool) string {
	c := strings.TrimSpace(color)
	// Remove quotes if present
	if len(c) >= 2 && ((c[0] == '"' && c[len(c)-1] == '"') || (c[0] == '\'' && c[len(c)-1] == '\'')) {
		c = c[1 : len(c)-1]
	}
	lc := strings.ToLower(c)
	// Named colors
	named := map[string]string{
		"black": "30", "red": "31", "green": "32", "yellow": "33", "blue": "34", "magenta": "35", "cyan": "36", "white": "37",
		"lightblack": "90", "lightred": "91", "lightgreen": "92", "lightyellow": "93", "lightblue": "94", "lightmagenta": "95", "lightcyan": "96", "lightwhite": "97",
		"lightblack": "90", "lightred": "91", "lightgreen": "92", "lightyellow": "93", "lightblue": "94", "lightmagenta": "95", "lightcyan": "96", "lightwhite": "97",
		// Also allow "lightBlack" variants already lowercased
	}
	if code, ok := named[lc]; ok {
		if background {
			// Convert foreground code to background: 30->40, 90->100 etc
			if strings.HasPrefix(code, "9") {
				// 90 -> 100, 91->101 etc
				num, _ := strconv.Atoi(code)
				return strconv.Itoa(num + 10)
			} else {
				num, _ := strconv.Atoi(code)
				return strconv.Itoa(num + 10)
			}
		}
		return code
	}
	// Also try direct named without lower? already
	// Hex color: #RRGGBB or #RGB ?
	if strings.HasPrefix(c, "#") {
		hex := c[1:]
		if len(hex) == 6 {
			r, err1 := strconv.ParseInt(hex[0:2], 16, 0)
			g, err2 := strconv.ParseInt(hex[2:4], 16, 0)
			b, err3 := strconv.ParseInt(hex[4:6], 16, 0)
			if err1 == nil && err2 == nil && err3 == nil {
				if background {
					return fmt.Sprintf("48;2;%d;%d;%d", r, g, b)
				}
				return fmt.Sprintf("38;2;%d;%d;%d", r, g, b)
			}
		} else if len(hex) == 3 {
			// #RGB -> expand?
			r, _ := strconv.ParseInt(string(hex[0])+string(hex[0]), 16, 0)
			g, _ := strconv.ParseInt(string(hex[1])+string(hex[1]), 16, 0)
			b, _ := strconv.ParseInt(string(hex[2])+string(hex[2]), 16, 0)
			if background {
				return fmt.Sprintf("48;2;%d;%d;%d", r, g, b)
			}
			return fmt.Sprintf("38;2;%d;%d;%d", r, g, b)
		}
	}
	// rgb(...) format
	// rgb(255,0,0) or rgb(0xFF,0xFF,0xFF)
	if strings.HasPrefix(lc, "rgb(") && strings.HasSuffix(lc, ")") {
		inner := c[4 : len(c)-1] // keep original case for hex parsing? use c
		// Actually extract from original c without lower? Use c
		innerOrig := strings.TrimSpace(c[4 : len(c)-1])
		parts := strings.Split(innerOrig, ",")
		if len(parts) == 3 {
			var r, g, b int64
			var err error
			for i, p := range parts {
				p = strings.TrimSpace(p)
				if strings.HasPrefix(strings.ToLower(p), "0x") {
					val, e := strconv.ParseInt(p[2:], 16, 0)
					if e != nil {
						err = e
						break
					}
					if i == 0 {
						r = val
					} else if i == 1 {
						g = val
					} else {
						b = val
					}
				} else {
					val, e := strconv.ParseInt(p, 10, 0)
					if e != nil {
						err = e
						break
					}
					if i == 0 {
						r = val
					} else if i == 1 {
						g = val
					} else {
						b = val
					}
				}
			}
			if err == nil {
				if background {
					return fmt.Sprintf("48;2;%d;%d;%d", r, g, b)
				}
				return fmt.Sprintf("38;2;%d;%d;%d", r, g, b)
			}
		}
		_ = inner
	}
	return ""
}

func (s Style) IsHide() bool {
	if s.Hide != nil {
		return *s.Hide
	}
	return false
}

// Filter holds state for processing lines
type Filter struct {
	cfg   *Config
	color bool
	// current state style for subsequent generic lines
	currentStyle Style
	// track if we have seen a style? For persistence, COVER does not persist
	hasCurrent bool
}

func NewFilter(cfg *Config, color bool) *Filter {
	return &Filter{cfg: cfg, color: color}
}

func (f *Filter) formatLabel(label string, style Style) string {
	if !f.color {
		return ""
	}
	ansi := styleToANSI(style)
	if ansi == "" {
		return ""
	}
	return ansi
}

func (f *Filter) applyRemovals(s string) string {
	for _, re := range f.cfg.removalsRe {
		s = re.ReplaceAllString(s, "")
	}
	return s
}

func (f *Filter) processLine(line string) string {
	// Preserve original for removals on output? We'll apply removals after formatting as per earlier analysis
	// But first classify
	originalLine := line

	// Check for BUILD: "^# (.+)"
	if m := regexp.MustCompile(`^#\s+(.+)`).FindStringSubmatch(line); m != nil {
		return f.handleBuild(m, originalLine)
	}
	// Check for START: "^=== RUN\s+Test(.*)"
	if m := regexp.MustCompile(`^=== RUN\s+Test(.*)`).FindStringSubmatch(line); m != nil {
		return f.handleStart(m, originalLine)
	}
	// Check for PASS: "^\s*--- PASS:\s+Test(.+)"
	if m := regexp.MustCompile(`^\s*--- PASS:\s+Test(.*)`).FindStringSubmatch(line); m != nil {
		return f.handlePass(m, originalLine)
	}
	if m := regexp.MustCompile(`^\s*--- FAIL:\s+Test(.*)`).FindStringSubmatch(line); m != nil {
		return f.handleFail(m, originalLine)
	}
	if m := regexp.MustCompile(`^\s*--- SKIP:\s+Test(.*)`).FindStringSubmatch(line); m != nil {
		return f.handleSkip(m, originalLine)
	}
	// Check for coverage: "^coverage: (\d+\.\d)% of statements$"
	if m := regexp.MustCompile(`^coverage: (\d+\.\d)% of statements$`).FindStringSubmatch(line); m != nil {
		return f.handleCover(m, originalLine)
	}
	// Check for PASS package: "^ok\s+(\S+)(.*)"
	if m := regexp.MustCompile(`^ok\s+(\S+)(.*)`).FindStringSubmatch(line); m != nil {
		// Need to validate ok package pattern: should be considered PASS package only if it matches expected format
		// We earlier observed that "ok  \tpkg\t0.003s (cached)" with space before (cached) is not considered PASS, but "ok  \tpkg\t(cached)" is.
		// To replicate, we will use a stricter regex that matches actual go output:
		// go outputs: "ok  \t<pkg>\t<time>[\tcoverage...]" or "ok  \t<pkg>\t(cached)[\tcoverage...]"? Actually cached format is "ok  \t<pkg>\t(cached)" with tab before (cached).
		// Let's define regex for valid PASS package: ^ok\s+\S+\s+(\([^)]+\)|\d+\.\d+s)(\s+\(cached\))?(\s+coverage:.*)?$? But we saw valid cases with time and coverage, and cached without time, but not time + space + (cached).
		// Simpler: we will accept any ok line that does NOT contain " (cached)" with space before (cached) after time? That's too specific.
		// For now, we will treat any line starting with "ok\s+" as PASS package, but we observed some ok lines with "(cached)" after time with space were treated as generic. Let's just implement the observed valid patterns and treat others as generic.
		// Let's use regex: ^ok\s+\S+\s+(\S+)(\s+.*)? and check if second field is "(cached)" or time or coverage?
		// Better to use the same logic as original: It likely uses a regex like `^ok\s+\S+(\s+\S+)*` but with coverage detection?
		// For simplicity, we will consider ok lines that contain " (cached)" with space (not tab) as generic, to match observation.
		if strings.Contains(line, " (cached)") {
			// This had space before (cached), not tab, so treat as generic
			// But what about "ok  \tpkg\t0.003s (cached)" - that was generic
			// Check if line contains "\t(cached)" with tab, then it's valid PASS (but we had valid "ok  \tpkg\t(cached)" which was PASS)
			// So we need to distinguish: "\t(cached)" vs " (cached)"
			if strings.Contains(line, "\t(cached)") {
				// valid with tab
			} else if strings.Contains(line, " (cached)") {
				// need to see if it's tab or space: if contains " (cached)" and not "\t(cached)", then generic
				// But our check already handles: if contains " (cached)" (space) then generic, even if also contains tab? For "ok  \tpkg\t0.003s (cached)" it contains " (cached)" -> generic -> correct
				// For "ok  \tpkg\t(cached)" it contains "\t(cached)" but also " (cached)"? Actually "\t(cached)" contains " (cached)"? No, because tab != space, so not.
				// So check: if strings.Contains(line, " (cached)") -> generic
				return f.handleGeneric(line, originalLine)
			}
		}
		// Also for lines with coverage after time but before (cached) etc, but those were generic as well when coverage had "(cached)"?
		// We already handled (cached) case, so now treat remaining ok as PASS
		return f.handlePassPackage(m, originalLine, line)
	}
	if m := regexp.MustCompile(`^FAIL\s+(\S+.*)`).FindStringSubmatch(line); m != nil {
		// Need to check if FAIL package is valid: we saw FAIL with "[build failed]" is FAIL, but "[setup failed]" is generic
		// Also FAIL with time vs without? Let's use logic: if line contains "[build failed]" or is "FAIL\t<pkg>\t<time>" or "FAIL\t<pkg> [build failed]" then FAIL, otherwise generic
		// For now, accept FAIL lines that either match "FAIL\s+\S+\s+[\d\.]+s" or "FAIL\s+\S+\s+\[build failed\]" or "FAIL\s+\S+\s+\[build failed\]" variations
		// Let's use regex to determine: if it matches "FAIL\s+\S+\s+\d" or "FAIL\s+\S+.*\[build failed\]" then FAIL, else generic
		if regexp.MustCompile(`^FAIL\s+\S+\s+[\d\.]+s`).MatchString(line) || strings.Contains(line, "[build failed]") {
			return f.handleFailPackage(m, originalLine, line)
		}
		// If it contains "[setup failed]" -> generic
		return f.handleGeneric(line, originalLine)
	}
	if m := regexp.MustCompile(`^\?\s+(\S+)\s+\[no test files\]`).FindStringSubmatch(line); m != nil {
		return f.handleSkipPackage(m, originalLine)
	}
	// Check for generic file:line pattern -> handle as generic but with file/line coloring inside
	// But generic handling will do file:line coloring as part of handleGeneric
	return f.handleGeneric(line, originalLine)
}

func (f *Filter) labelString(longLabel, shortLabel string) string {
	switch f.cfg.LabelType {
	case "short":
		return shortLabel
	case "none":
		return ""
	default: // long
		return longLabel
	}
}

func (f *Filter) prefixForStyle(style Style, label string) string {
	if !f.color {
		return ""
	}
	ansi := styleToANSI(style)
	reset := "\x1b[0m"
	if label == "" {
		// For none, just color the content? Actually for none, we still color content with style, but no label prefix
		// The prefix is empty, but content will be colored.
		// For generic lines with none, prefix is empty (as observed)
		// For labeled lines with none, we return just colored content without label.
		// This function is not used for none? We'll handle differently.
		return ""
	}
	if ansi == "" {
		return label
	}
	// For style with color, we need to wrap label and content? Actually we format as "<ansi><label><reset>"? Let's see observed: "\x1b[90mSTART| Foo\x1b[0m" - the ansi before label and reset after content.
	// So we should generate prefix as ansi + label + reset? But then content after label also colored? In observed, the content after label is also colored with same ansi until reset.
	// For example, START| Foo is entirely within \x1b[90m ... \x1b[0m
	// So we can just return ansi + label, and caller will add content and then reset.
	_ = reset
	return ansi + label
}

func (f *Filter) handleBuild(m []string, original string) string {
	style := f.cfg.BuildStyle
	if style.IsHide() && f.color {
		return f.applyRemovals("")
	}
	var out string
	if f.color {
		label := f.labelString("BUILD| ", "!! ")
		// For long, BUILD| has no space? Actually observed "BUILD| pkg" (no space before |, one space after). For short "!! pkg"
		// For none, just "pkg"
		if f.cfg.LabelType == "long" {
			label = "BUILD| "
		} else if f.cfg.LabelType == "short" {
			label = "!! "
		} else {
			label = ""
		}
		// Need to adjust label for long: earlier we used "BUILD| " but need to check exact: For long, we had "BUILD| pkg" (5+1+1) => "BUILD| " (6 chars inc space). For short "!! " (2+1)
		// For none, just ""
		content := m[1]
		ansi := styleToANSI(style)
		if ansi != "" {
			if label != "" {
				out = ansi + label + content + "\x1b[0m"
			} else {
				out = ansi + content + "\x1b[0m"
			}
		} else {
			out = label + content
		}
		// For hide false, BUILD line is shown; after this, set current style to Build for subsequent generic lines
		f.currentStyle = style
		f.hasCurrent = true
	} else {
		out = original
		f.currentStyle = Style{}
		f.hasCurrent = false
	}
	out = f.applyRemovals(out)
	// For color disabled, original line is returned without removals? But removals should still apply? Earlier we saw removals with no color? Not tested. We'll apply removals regardless.
	// Actually removals should be applied even without color? Let's apply.
	if !f.color {
		// For non-color, removals via output would be on original
		// We already applied? But we set out=original, then applyRemovals will remove substring.
		// The original test for removals was with force color, so not needed.
	}
	return out + "\n"
}

func (f *Filter) handleStart(m []string, original string) string {
	style := f.cfg.StartStyle
	if style.IsHide() && f.color {
		return f.applyRemovals("")
	}
	rest := m[1] // after Test, includes maybe "", "Foo", "Foo/Bar", etc
	// rest is after Test, e.g., for TestFoo, m[1] = "Foo"; for TestFoo/Bar, "Foo/Bar"; for Test (empty), ""
	// Need to handle leaveTestPrefix
	var display string
	if f.cfg.LeaveTestPrefix {
		display = "Test" + rest
	} else {
		display = rest
	}
	// Handle indentation for subtests: count slashes? For TestFoo/Bar, rest="Foo/Bar", display accordingly
	// Need to compute indent based on depth? For Start, we saw indent spaces after label increase with slash count.
	// Let's determine indent: For "Foo" -> no extra indent, "Foo/Bar" -> "  " + "Foo/Bar", "Foo/Bar/Baz" -> "    " + "Foo/Bar/Baz"?
	// Actually observed for START|   Foo/Bar (3 spaces), for START|     Foo/Bar/Baz (5 spaces)
	// So indent = (depth-1)*2 + 1? For depth 1 (no slash): 1 space after label, not indent. Wait label already includes trailing space.
	// For long, label is "START| " (with one space after |). Then for Foo, content is "Foo" => "START| Foo"
	// For Foo/Bar, content is "  Foo/Bar" with 2 extra spaces before Foo? But observed was "START|   Foo/Bar" (3 spaces after |). That's label "START| " (which is "START| " = 7 chars) plus "  Foo/Bar" (2 spaces + content) = total 3 spaces after |? Actually label already has one space, plus 2 extra = 3.
	// So indent for subtest is added before display content.
	var indent string
	if strings.Contains(display, "/") {
		parts := strings.Split(display, "/")
		depth := len(parts)
		// depth 2 => 2 spaces, depth 3 => 4 spaces, depth 4 => 6 spaces? Let's see: For Foo/Bar (depth 2) we had 2 extra spaces, for Foo/Bar/Baz (depth3) we had 4 extra spaces, for Foo/Bar/Baz/Qux (depth4) we had 6 extra spaces.
		// So extra = (depth-1)*2
		extra := (depth - 1) * 2
		indent = strings.Repeat(" ", extra)
	}
	content := indent + display
	// Also need to handle #01? That's not slash, so no indent

	var out string
	if f.color {
		var label string
		switch f.cfg.LabelType {
		case "short":
			label = ">  "
		case "none":
			label = ""
		default:
			label = "START| "
		}
		ansi := styleToANSI(style)
		if label == "" {
			if ansi != "" {
				out = ansi + content + "\x1b[0m"
			} else {
				out = content
			}
		} else {
			if ansi != "" {
				out = ansi + label + content + "\x1b[0m"
			} else {
				out = label + content
			}
		}
		f.currentStyle = style
		f.hasCurrent = true
	} else {
		out = original
		// Do not set current for non-color?
		f.hasCurrent = false
	}
	out = f.applyRemovals(out)
	if out == "" {
		return ""
	}
	if out == "" {
		return ""
	}
	// If removals made output empty, return empty (no newline?)
	// For hide, we already returned empty
	if out == "" {
		return ""
	}
	// Ensure newline added? Original handleBuild added "\n" directly, but if removals empties, we should not add newline? For hide we returned empty without newline. For removals that result in empty string, the original behavior for ".* removal" gave empty (no line). So we should return "" without newline.
	if out == "" {
		return ""
	}
	return out + "\n"
}

func (f *Filter) handlePass(m []string, original string) string {
	style := f.cfg.PassStyle
	if style.IsHide() && f.color {
		// Hide pass lines
		return f.applyRemovals("")
	}
	// m[1] is rest after Test, may include "Foo (0.00s)" etc
	// Need to separate test name and optional duration
	// m is from `--- PASS:\s+Test(.*)` which captures rest including "Foo (0.00s)" or "Foo"
	rest := m[1]
	// rest includes everything after Test, e.g., "Foo (0.00s)", "Foo", "Foo/Bar (0.00s)"
	// We need to parse test name and duration
	// The test name is up to " (" if exists, else whole
	var testPart, duration string
	if idx := strings.Index(rest, " ("); idx != -1 {
		testPart = rest[:idx]
		// rest[idx+1:] is "(0.00s)" maybe
		duration = rest[idx:] // includes " (0.00s)"
		// Actually rest[idx:] is " (0.00s)" with leading space
	} else {
		testPart = rest
	}
	// Apply leaveTestPrefix
	var displayTest string
	if f.cfg.LeaveTestPrefix {
		displayTest = "Test" + testPart
	} else {
		displayTest = testPart
	}
	// Handle indent for subtests similar to start
	var indent string
	if strings.Contains(displayTest, "/") {
		parts := strings.Split(displayTest, "/")
		depth := len(parts)
		extra := (depth - 1) * 2
