		switch f.cfg.LabelType {
		case "short":
			label = "%  "
		case "none":
			label = ""
		default:
			label = "COVER| "
		}
		content := fmt.Sprintf("%s%% [%s]", coverageStr, bar)
		ansi := styleToANSI(style)
		if label == "" {
			if ansi != "" {
				out = ansi + content + "\x1b[0m"
			} else {
				out = content
			}
		} else {
			if ansi != "" {
				out = ansi + label + content + "\x1b[0m"
			} else {
				out = label + content
			}
		}
		// Cover does NOT set currentStyle persistence? Earlier we saw after cover, hello was not colored.
		// So we should NOT set hasCurrent, or set but then generic after cover will be not colored.
		// To make generic after cover not inherit, we can reset hasCurrent to false.
		f.hasCurrent = false
	} else {
		out = original
		f.hasCurrent = false
	}
	out = f.applyRemovals(out)
	if out == "" {
		return ""
	}
	return out + "\n"
}

