// isTerminal checks if fd is a terminal using ioctl TCGETS
func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return err == 0
}

func shouldColor() bool {
	if os.Getenv("RICHGO_FORCE_COLOR") == "1" {
		return true
	}
	return isTerminal(os.Stdout.Fd())
}

// styleToANSI converts Style to ANSI escape sequence (without reset)
func styleToANSI(s Style) string {
	var codes []string
	if s.Bold != nil && *s.Bold {
		codes = append(codes, "1")
	}
	if s.Faint != nil && *s.Faint {
		codes = append(codes, "2")
	}
	if s.Italic != nil && *s.Italic {
		codes = append(codes, "3")
	}
	if s.Underline != nil && *s.Underline {
		codes = append(codes, "4")
	}
	if s.BlinkSlow != nil && *s.BlinkSlow {
		codes = append(codes, "5")
	}
	if s.BlinkRapid != nil && *s.BlinkRapid {
		codes = append(codes, "6")
	}
	if s.Inverse != nil && *s.Inverse {
		codes = append(codes, "7")
	}
	if s.Conceal != nil && *s.Conceal {
		codes = append(codes, "8")
	}
	if s.CrossOut != nil && *s.CrossOut {
		codes = append(codes, "9")
	}
	if s.Frame != nil && *s.Frame {
		codes = append(codes, "51")
	}
	if s.Encircle != nil && *s.Encircle {
		codes = append(codes, "52")
	}
	if s.Overline != nil && *s.Overline {
		codes = append(codes, "53")
	}
	if s.Foreground != nil {
		if code := colorToCode(*s.Foreground, false); code != "" {
			codes = append(codes, code)
		}
	}
	if s.Background != nil {
		if code := colorToCode(*s.Background, true); code != "" {
			codes = append(codes, code)
		}
	}
	if len(codes) == 0 {
		return ""
	}
	return "\x1b[" + strings.Join(codes, ";") + "m"
}

func colorToCode(color string, background bool) string {
	c := strings.TrimSpace(color)
	// Remove quotes if present
	if len(c) >= 2 && ((c[0] == '"' && c[len(c)-1] == '"') || (c[0] == '\'' && c[len(c)-1] == '\'')) {
