				num, _ := strconv.Atoi(code)
				return strconv.Itoa(num + 10)
			}
		}
		return code
	}
	// Also try direct named without lower? already
	// Hex color: #RRGGBB or #RGB ?
	if strings.HasPrefix(c, "#") {
		hex := c[1:]
		if len(hex) == 6 {
			r, err1 := strconv.ParseInt(hex[0:2], 16, 0)
			g, err2 := strconv.ParseInt(hex[2:4], 16, 0)
			b, err3 := strconv.ParseInt(hex[4:6], 16, 0)
			if err1 == nil && err2 == nil && err3 == nil {
				if background {
