				}
				return fmt.Sprintf("38;2;%d;%d;%d", r, g, b)
			}
		} else if len(hex) == 3 {
			// #RGB -> expand?
			r, _ := strconv.ParseInt(string(hex[0])+string(hex[0]), 16, 0)
			g, _ := strconv.ParseInt(string(hex[1])+string(hex[1]), 16, 0)
			b, _ := strconv.ParseInt(string(hex[2])+string(hex[2]), 16, 0)
			if background {
