		if len(parts) == 3 {
			var r, g, b int64
			var err error
			for i, p := range parts {
				p = strings.TrimSpace(p)
				if strings.HasPrefix(strings.ToLower(p), "0x") {
					val, e := strconv.ParseInt(p[2:], 16, 0)
					if e != nil {
						err = e
						break
					}
					if i == 0 {
						r = val
					} else if i == 1 {
						g = val
					} else {
						b = val
					}
				} else {
					val, e := strconv.ParseInt(p, 10, 0)
					if e != nil {
						err = e
						break
					}
					if i == 0 {
						r = val
					} else if i == 1 {
