	coverage, _ := strconv.ParseFloat(coverageStr, 64)
	var style Style
	if coverage >= float64(f.cfg.CoverThreshold) {
		style = f.cfg.CoveredStyle
	} else {
		style = f.cfg.UncoveredStyle
	}
	if style.IsHide() && f.color {
		return f.applyRemovals("")
	}
	// Generate bar: 10 chars, # for each 10%, _ for rest
	filled := int(coverage / 10)
	if filled > 10 {
		filled = 10
	}
	if filled < 0 {
		filled = 0
	}
	bar := strings.Repeat("#", filled) + strings.Repeat("_", 10-filled)
	var out string
	if f.color {
		var label string
		switch f.cfg.LabelType {
		case "short":
			label = "%  "
		case "none":
			label = ""
		default:
			label = "COVER| "
		}
		content := fmt.Sprintf("%s%% [%s]", coverageStr, bar)
		ansi := styleToANSI(style)
		if label == "" {
			if ansi != "" {
				out = ansi + content + "\x1b[0m"
			} else {
				out = content
			}
		} else {
			if ansi != "" {
				out = ansi + label + content + "\x1b[0m"
			} else {
				out = label + content
			}
		}
		// Cover does NOT set currentStyle persistence? Earlier we saw after cover, hello was not colored.
		// So we should NOT set hasCurrent, or set but then generic after cover will be not colored.
		// To make generic after cover not inherit, we can reset hasCurrent to false.
		f.hasCurrent = false
	} else {
		out = original
		f.hasCurrent = false
	}
	out = f.applyRemovals(out)
	if out == "" {
		return ""
	}
	return out + "\n"
}

